Everything between the six models and the bench: one adapter per model behind a single predict(state, questions) signature, the bench itself, and the summariser that reads its JSON output. jevclient.py — the adapter layer — six adapters behind one predict(state, questions) call . #!/usr/bin/env python3 """ jet-tut — unified typed-decision client. Every model in this tutorial answers the same question shape: state : str (text, ticket, log line, JSON ...) questions : {"id": {"type": "noul"|"choice"|"score", "instructions": "...", "criteria": {...} | [...]}} -&gt; {"answers": {"id": {"label": str, "probabilities": {opt: float}, "raw": ...}}} Each adapter below hides the model's real request format behind that shape. Run `python jevclient.py --list` to see what is available. """ from __future__ import annotations import base64 import json import math import os import re import sys import time from pathlib import Path from typing import Any ROOT = Path(os.environ.get("JET_ROOT", Path.home() / "jet-tut")) MODELS = ROOT / "models" # `trust_remote_code` dynamic module cache. The default under # ~/.cache/huggingface/modules may be root-owned on a shared box; point it # somewhere we know is writable so `get_class_from_dynamic_module` works. os.environ.setdefault("HF_MODULES_CACHE", str(ROOT / ".hf-modules")) Path(os.environ["HF_MODULES_CACHE"]).mkdir(parents=True, exist_ok=True) # -------------------------------------------------------------------------- # helpers # -------------------------------------------------------------------------- def _to_dict(crit: Any) -&gt; dict[str, str | None]: """Normalise `criteria` into an ordered {id: description} mapping.""" if crit is None: return {} if isinstance(crit, dict): return {str(k): (None if v is None else str(v)) for k, v in crit.items()} if isinstance(crit, list): return {str(c): (c if isinstance(c, str) else None) for c in crit} raise TypeError(f"unsupported criteria type: {type(crit)!r}") def _softmax(xs: list[float]) -&gt; list[float]: m = max(xs) es = [math.exp(x - m) for x in xs] s = sum(es) return [e / s for e in es] class Adapter: """Base class. Subclasses implement `predict`.""" name = "base" def predict(self, state: str, questions: dict) -&gt; dict: raise NotImplementedError def close(self) -&gt; None: # optional pass # -------------------------------------------------------------------------- # 1. hotchpotch/bekko-system-one-v0-17m (shared-prefix encoder, 17M) # -------------------------------------------------------------------------- class BekkoAdapter(Adapter): name = "bekko-17m" def __init__(self, model_dir: str | Path = MODELS / "bekko-17m", device: str = "cuda"): from transformers.dynamic_module_utils import get_class_from_dynamic_module repo = str(model_dir) cls = get_class_from_dynamic_module( "inference_v0.BekkoSentenceTransformer", repo, trust_remote_code=True, ) self.model = cls(repo, trust_remote_code=True, device=device, attn_implementation="sdpa") def _decision(self, qid: str, q: dict) -&gt; dict: kind = q["type"] crit = _to_dict(q.get("criteria")) if kind == "score": # expect criteria to be a list of ordered numeric levels items, values = [], [] for i, c in enumerate(q.get("criteria") or []): # accept either plain labels 0..n-1 or {"id","value"} if isinstance(c, dict): items.append({ "id": str(c.get("id", i)), "description_json": json.dumps(str(c.get("description", c.get("id")))), "value": float(c["value"]), }) values.append(float(c["value"])) else: items.append({ "id": str(i), "description_json": json.dumps(str(c)), "value": float(i), }) values.append(float(i)) elif kind == "noul": items = [ {"id": "false", "description_json": json.dumps(crit.get("false", "No.")), "value": None}, {"id": "true", "description_json": json.dumps(crit.get("true", "Yes.")), "value": None}, ] else: items = [ { "id": k, "description_json": json.dumps(v if v else k), "value": None, } for k, v in crit.items() ] return { "id": qid, "kind": "judgment", "type": kind, "instructions_json": json.dumps(q["instructions"]), "system_prompt": "", "criteria": items, "documents": [], "scoring": None, } def predict(self, state: str, questions: dict) -&gt; dict: payload = { "state_json": json.dumps({"state": state}), "decisions": [self._decision(qid, q) for qid, q in questions.items()], } out = self.model.predict(payload) answers = {} for qid, q in questions.items(): r = out[qid] kind = q["type"] probs = {str(k).lower(): float(v) for k, v in (r.get("probabilities") or {}).items()} if kind == "score": sc = float(r.get("score")) answers[qid] = { "label": f"{sc:.3f}", "probabilities": probs, "raw": {k: r.get(k) for k in ("score", "normalized_score", "values")}, } elif kind == "noul": p = float(r.get("probability_yes", probs.get("true", 0.5))) answers[qid] = { "label": "true" if p &gt;= 0.5 else "false", "probabilities": {"false": 1 - p, "true": p}, "raw": r, } else: answers[qid] = { "label": r.get("selected_id"), "probabilities": probs, "raw": r, } return {"answers": answers} # -------------------------------------------------------------------------- # 2. convaiinnovations/laya (ModernBERT-large, non-autoregressive, 421M) # -------------------------------------------------------------------------- class LayaAdapter(Adapter): name = "laya" def __init__(self, model_dir: str | Path = MODELS / "laya", model: str = "english", device: str = "cuda"): import laya if model == "english": self.agent = laya.load(str(model_dir)) else: self.agent = laya.load(str(model_dir), subfolder=model) if device == "cuda": self.agent.cfg["device"] = "cuda" def predict(self, state: str, questions: dict) -&gt; dict: res = self.agent.predict(state, questions) answers = {} for qid, q in questions.items(): a = res["answers"][qid] t = q["type"] if t == "noul": p = float(a.get("noul", a.get("probability_yes", 0.5))) answers[qid] = { "label": "true" if p &gt;= 0.5 else "false", "probabilities": {"false": 1 - p, "true": p}, "raw": a, } elif t == "score": sc = a.get("score") sc = float(sc) if sc is not None else float("nan") n = len(q.get("criteria") or []) answers[qid] = { "label": f"{sc:.3f}", "probabilities": {}, "raw": {"score": sc, "normalized": a.get("normalised_score") or a.get("normalized_score")}, } else: probs = {k: float(v) for k, v in (a.get("probabilities") or {}).items()} answers[qid] = { "label": a.get("choice"), "probabilities": probs, "raw": a, } return {"answers": answers} # -------------------------------------------------------------------------- # 3. akhilaaa3/Jev-Omni (Gemma 4 12B IT — text / image / audio / video) # -------------------------------------------------------------------------- class JevOmniAdapter(Adapter): """ Loads `jev_omni.load_jev_omni()` from the model's own repo code. The shipped loader calls `snapshot_download(...)` to fetch the ~24 GB of Gemma 4 weights from the Hub cache; here we redirect that to the `models/jev-omni` folder we already downloaded so everything stays under `~/jet-tut`. """ name = "jev-omni" def __init__(self, model_dir: str | Path = MODELS / "jev-omni"): import importlib.util model_dir = Path(model_dir).resolve() spec = importlib.util.spec_from_file_location("jev_omni", model_dir / "jev_omni.py") ju = importlib.util.module_from_spec(spec) sys.modules["jev_omni"] = ju spec.loader.exec_module(ju) missing = [n for n in ("model*.safetensors", "head.pt", "config.json") if not any(model_dir.glob(n))] if missing: raise RuntimeError( f"jev-omni: {missing} not found — run " f"`bash scripts/01-download.sh omni` first" ) # Redirect the loader's own `snapshot_download(...)` to our folder. ju.snapshot_download = lambda *a, **k: str(model_dir) self.clf = ju.load_jev_omni() def _one(self, state: str, q: dict, media: str | None = None, modality: str | None = None): kind = q["type"] if kind == "noul": # Jev-Omni `predict()` takes free-form options; we use the same literal # strings as the bench ("true"/"false") so labels line up automatically. options = ["true", "false"] elif kind == "score": options = [str(c) for c in (q.get("criteria") or [])] else: options = list(_to_dict(q.get("criteria")).keys()) kw = {} if media and modality: kw = {"media": media, "modality": modality} return self.clf.predict( state=state, question=q["instructions"], options=options, **kw, ), options def predict(self, state: str, questions: dict, media: str | None = None, modality: str | None = None) -&gt; dict: answers = {} for qid, q in questions.items(): (r, options) = self._one(state, q, media, modality) probs = {k: float(v) for k, v in (r.get("probabilities") or {}).items()} kind = q["type"] if kind == "score": # prediction is the winning level *label*; convert to its index # so score MAE is comparable across models. try: idx = options.index(r.get("prediction")) except ValueError: idx = None label = f"{idx:.3f}" if idx is not None else None else: label = r.get("prediction") answers[qid] = { "label": label, "probabilities": probs, "raw": r, } return {"answers": answers} # -------------------------------------------------------------------------- # 4. autotrust/JEV-9B (vLLM + `jev-decision` LoRA + 24-slot decision head) # -------------------------------------------------------------------------- class JEV9BAdapter(Adapter): """ Works against a vLLM server started with: vllm serve models/JEV-9B --served-model-name autotrust/JEV-9B \ --enable-lora --max-lora-rank 32 \ --lora-modules jev-decision=models/JEV-9B/adapter_vllm \ --logprobs-mode processed_logprobs --max-model-len 4096 """ name = "jev9b" def __init__(self, base_url: str = "http://localhost:8104", model_dir: str | Path = MODELS / "JEV-9B"): import requests self.s = requests.Session() self.url = base_url.rstrip("/") dh_path = Path(model_dir) / "adapter_vllm" / "decision_head.json" cal_path = Path(model_dir) / "calibration.json" self.dh = json.loads(dh_path.read_text()) self.T = json.loads(cal_path.read_text())["per_kind"] def _decide(self, kind: str, state: str, question: str, options: list[str]) -&gt; dict[str, float]: letters = "ABCDEFGHIJKLMNOP" if kind == "noul": lines = ["false", "true"] elif kind == "score": lines = [str(i) for i in range(len(options))] else: lines = [f"{letters[i]}) {o}" for i, o in enumerate(options)] prompt = ( f"[kind] {kind}
[state] {state}
[question] {question}
[options]
" + "
".join(lines) + "
[decision]:" ) s, _ = self.dh["slots"]["ranges"][kind] ids = self.dh["verbalizer_ids"][s : s + len(lines)] r = self.s.post( f"{self.url}/v1/completions", json={ "model": "jev-decision", "prompt": prompt, "max_tokens": 1, "temperature": 1.0, "logprobs": len(ids), "allowed_token_ids": ids, "add_special_tokens": False, "return_tokens_as_token_ids": True, }, timeout=120, ).json() tlp = r["choices"][0]["logprobs"]["top_logprobs"][0] lp = {} for k, v in tlp.items(): tok = int(k.split(":")[1]) if ":" in k else int(k) lp[tok] = v z = [(lp.get(t, -1e9) + self.dh["bias"][s + i]) / self.T[kind] for i, t in enumerate(ids)] e = _softmax(z) return {o: p for o, p in zip(options if kind not in ("noul", "score") else lines, e)} def predict(self, state: str, questions: dict) -&gt; dict: answers = {} for qid, q in questions.items(): kind = q["type"] if kind == "noul": opts = ["false", "true"] elif kind == "score": opts = [str(i) for i in range(len(q.get("criteria") or [0] * 6))] else: opts = list(_to_dict(q.get("criteria")).keys()) probs = self._decide(kind, state, q["instructions"], opts) label = max(probs, key=probs.get) if kind == "score": ev = sum(float(k) * v for k, v in probs.items()) label = f"{ev:.3f}" answers[qid] = {"label": label, "probabilities": probs, "raw": probs} return {"answers": answers} # -------------------------------------------------------------------------- # 5. openjev/openjev (27B + helper/shim.py -&gt; POST /v1/systemone) # -------------------------------------------------------------------------- class OpenJevAdapter(Adapter): """ Talks to `helper/shim.py`, the calibration shim that follows vLLM in the openjev recipe. Shape follows `POST /v1/systemone`: in : {state, questions: {id: {type, instructions, criteria}}} out: {answers: {id: {choice|noul|score, probabilities, confidence}}} """ name = "openjev" def __init__(self, base_url: str = "http://localhost:8106", timeout: float = 120.0): import requests self.s = requests.Session() self.url = base_url.rstrip("/") self.timeout = timeout def predict(self, state: str, questions: dict) -&gt; dict: q = {} for qid, qu in questions.items(): kind = qu["type"] if kind == "score": q[qid] = {"type": "score", "instructions": qu["instructions"], "criteria": [str(c) for c in (qu.get("criteria") or [])]} elif kind == "noul": q[qid] = {"type": "noul", "instructions": qu["instructions"]} else: q[qid] = {"type": "choice", "instructions": qu["instructions"], "criteria": dict(_to_dict(qu.get("criteria")))} r = self.s.post( f"{self.url}/v1/systemone", json={"model": "openjev", "state": state, "questions": q}, timeout=self.timeout, ) r.raise_for_status() body = r.json() answers = {} for qid, qu in questions.items(): a = body["answers"][qid] kind = qu["type"] probs = {str(k).lower(): float(v) for k, v in (a.get("probabilities") or {}).items()} if kind == "noul": p = float(a.get("noul", 0.5)) answers[qid] = { "label": "true" if p &gt;= 0.5 else "false", "probabilities": {"false": 1 - p, "true": p}, "raw": a, } elif kind == "score": sc = float(a.get("score")) answers[qid] = { "label": f"{sc:.3f}", "probabilities": probs, "raw": a, } else: answers[qid] = { "label": a.get("choice"), "probabilities": probs, "raw": a, } return {"answers": answers} # -------------------------------------------------------------------------- # 6. TokenRhythm/NeoHorse-Jev-4B (the `neohorse_decision` runtime in the bundle) # -------------------------------------------------------------------------- class NeoHorseAdapter(Adapter): """ Uses the native Python wheel that ships inside the model bundle (`dist/neohorse_decision-*.whl`). No vLLM or SGLang needed. pip install --no-deps models/NeoHorse-Jev-4B/dist/neohorse_decision-*.whl """ name = "neohorse" def __init__(self, bundle: str | Path = MODELS / "NeoHorse-Jev-4B"): from neohorse_decision import DecisionEngine # type: ignore self.engine = DecisionEngine(str(bundle)) def predict(self, state: str, questions: dict) -&gt; dict: q = {} for qid, qu in questions.items(): entry = {"type": qu["type"], "instructions": qu["instructions"]} if qu["type"] == "choice": entry["criteria"] = dict(_to_dict(qu.get("criteria"))) elif qu["type"] == "score": entry["criteria"] = [str(c) for c in (qu.get("criteria") or [])] q[qid] = entry res = self.engine.predict({"state": state, "questions": q}) answers = {} for qid, qu in questions.items(): a = res["answers"][qid] t = qu["type"] if t == "noul": p = float(a.get("noul", a.get("probability_yes", 0.5))) answers[qid] = { "label": "true" if p &gt;= 0.5 else "false", "probabilities": {"false": 1 - p, "true": p}, "raw": a, } elif t == "score": sc = float(a.get("score")) answers[qid] = { "label": f"{sc:.3f}", "probabilities": {}, "raw": a, } else: probs = {k: float(v) for k, v in (a.get("probabilities") or {}).items()} answers[qid] = { "label": a.get("choice"), "probabilities": probs, "raw": a, } return {"answers": answers} ADAPTERS = { "bekko-17m": BekkoAdapter, "laya": LayaAdapter, "jev-omni": JevOmniAdapter, "jev9b": JEV9BAdapter, "openjev": OpenJevAdapter, "neohorse": NeoHorseAdapter, } if __name__ == "__main__": if "--list" in sys.argv or not sys.argv[1:]: for k, v in ADAPTERS.items(): print(f"{k:12s} {v.__doc__ or v.__name__}".splitlines()[0]) sys.exit(0) name = sys.argv[1] ad = ADAPTERS[name]() print(ad.predict( "Customer: charged twice for order #4411, wants a refund today.", {"dept": {"type": "choice", "instructions": "Which department should handle this?", "criteria": {"billing": "payments and refunds", "technical": "bugs and outages", "sales": "pricing"}}}, )) . bench.py — accuracy, score MAE, ECE, flip and p50/p95 latency for one model . #!/usr/bin/env python3 """ jet-tut — runs one model over the shared 25-question bench set. Usage: python bench.py &lt;model&gt; [--set scripts/bench-set.json] [--shuffle N] [--seed 1234] [--out out/bench-&lt;model&gt;.json] &lt;model&gt; is a key of jevclient.ADAPTERS. Reports accuracy (noul, choice), score MAE, calibration (ECE), option-shuffle flip rate and per-question p50 / p95 latency. """ from __future__ import annotations import argparse import copy import json import random import statistics import sys import time from pathlib import Path ROOT = Path(__file__).resolve().parent.parent sys.path.insert(0, str(Path(__file__).resolve().parent)) from jevclient import ADAPTERS # noqa: E402 def load_set(path: Path) -&gt; dict: return json.loads(path.read_text()) def expected_label(item: dict, score_levels: list[str]) -&gt; str: if item["kind"] == "score": return str(item["expect"]) return str(item["expect"]).lower() def norm_label(label, kind: str) -&gt; str | None: """Normalise a prediction label so "2", "2.0" and "2.000" all compare equal. Adapters report score labels as f"{x:.3f}" (e.g. "2.000") while this bench rounds to the level index ("2"); without normalising, every score re-ask counted as a spurious flip and inflated the measured flip rate. """ if label is None: return None if kind == "score": try: return str(round(float(label))) except (TypeError, ValueError): return str(label).lower() return str(label).lower() def option_set(item: dict, score_levels: list[str]) -&gt; list[str]: if item["kind"] == "noul": return ["false", "true"] if item["kind"] == "score": return [str(i) for i in range(len(score_levels))] return list(item["criteria"].keys()) def ece(conf: list[float], correct: list[bool], bins: int = 10) -&gt; float: if not conf: return float("nan") edges = [i / bins for i in range(bins + 1)] total = len(conf) out = 0.0 for b in range(bins): sel = [(c, k) for c, k in zip(conf, correct) if edges[b] &lt;= c &lt; edges[b + 1] or (b == bins - 1 and c == 1.0)] if not sel: continue acc = sum(1 for _, k in sel if k) / len(sel) avg = sum(c for c, _ in sel) / len(sel) out += (len(sel) / total) * abs(acc - avg) return out def run(model_name: str, items: list[dict], score_levels: list[str], repeat: int = 1, shuffle: int = 0, seed: int = 1234) -&gt; dict: ad = ADAPTERS[model_name]() rng = random.Random(seed) noul_rows, choice_rows, score_rows = [], [], [] latencies: list[float] = [] flips = 0 flip_total = 0 for item in items: qid = item["id"] q = { "type": item["kind"], "instructions": item["question"], "criteria": item.get("criteria", None) if item["kind"] != "score" else score_levels, } t0 = time.perf_counter() try: res = ad.predict(item["state"], {qid: q})["answers"][qid] except Exception as e: # noqa: BLE001 res = {"label": None, "probabilities": {}, "error": f"{type(e).__name__}: {e}"} dt = time.perf_counter() - t0 latencies.append(dt) exp = expected_label(item, score_levels) probs = {str(k).lower(): float(v) for k, v in (res.get("probabilities") or {}).items()} if item["kind"] == "score": lab = res.get("label") try: pred = round(float(lab)) except (TypeError, ValueError): pred = None score_rows.append({ "id": qid, "expect": int(exp), "pred": pred, "score": lab, "probabilities": probs, "seconds": dt, **({"error": res["error"]} if "error" in res else {}), }) else: pred = (res.get("label") or "").lower() best = max(probs, key=probs.get) if probs else None conf = probs.get(pred, probs.get(best, float("nan"))) if probs else float("nan") ok = pred == exp row = { "id": qid, "expect": exp, "pred": pred, "best": best, "conf": conf, "correct": ok, "probabilities": probs, "seconds": dt, **({"error": res["error"]} if "error" in res else {}), } (noul_rows if item["kind"] == "noul" else choice_rows).append(row) # ---- option-shuffle flip rate ------------------------------------- for k in range(shuffle): opts = option_set(item, score_levels) if len(opts) &lt; 2: continue order = opts[:] rng.shuffle(order) crit = None if item["kind"] == "choice": base = item["criteria"] crit = {o: base.get(o, "") for o in order} elif item["kind"] == "score": crit = order q2 = {"type": item["kind"], "instructions": item["question"], "criteria": crit} try: r2 = ad.predict(item["state"], {qid: q2})["answers"][qid] except Exception: # noqa: BLE001 continue lab2 = norm_label(r2.get("label"), item["kind"]) lab1 = norm_label(res.get("label"), item["kind"]) if lab2 is None or lab1 is None: continue flip_total += 1 if lab2 != lab1: flips += 1 def acc(rows): good = [r for r in rows if "error" not in r] return (sum(1 for r in good if r["correct"]) / len(good)) if good else float("nan") confs = [r["conf"] for r in noul_rows + choice_rows if "error" not in r] corrs = [r["correct"] for r in noul_rows + choice_rows if "error" not in r] errs = [abs(r["pred"] - r["expect"]) for r in score_rows if r["pred"] is not None] out = { "model": model_name, "n_items": len(items), "accuracy": { "noul": acc(noul_rows), "choice": acc(choice_rows), "overall_text": acc(noul_rows + choice_rows), }, "score_mae": (sum(errs) / len(errs)) if errs else None, "ece_10bin": ece(confs, corrs), "flip_rate": (flips / flip_total) if flip_total else None, "latency_seconds": { "p50": statistics.median(latencies) if latencies else None, "p95": sorted(latencies)[int(len(latencies) * 0.95) - 1] if len(latencies) &gt;= 2 else None, "mean": sum(latencies) / len(latencies) if latencies else None, "all": latencies, }, "rows": {"noul": noul_rows, "choice": choice_rows, "score": score_rows}, } return out def main() -&gt; int: p = argparse.ArgumentParser() p.add_argument("model") p.add_argument("--set", default=str(ROOT / "scripts" / "bench-set.json")) p.add_argument("--out", default=None) p.add_argument("--shuffle", type=int, default=0, help="how many shuffled re-asks per item to measure flip rate") p.add_argument("--seed", type=int, default=1234) a = p.parse_args() ds = load_set(Path(a.set)) items = ds["items"] levels = ds["score_levels"] res = run(a.model, items, levels, shuffle=a.shuffle, seed=a.seed) out_path = Path(a.out or (ROOT / "out" / f"bench-{a.model}.json")) out_path.parent.mkdir(parents=True, exist_ok=True) out_path.write_text(json.dumps(res, indent=2)) print(f"=== {a.model} ===") print(json.dumps({k: v for k, v in res.items() if k != "rows"}, indent=2)[:2000]) print(f"
wrote {out_path}") return 0 if __name__ == "__main__": raise SystemExit(main()) . summary.py — every out/bench-*.json on one line . #!/usr/bin/env python3 """Print a compact one-line summary for every out/bench-*.json.""" import json import sys from pathlib import Path here = Path(__file__).resolve().parent for p in sorted((here.parent / "out").glob("bench-*.json")): d = json.loads(p.read_text()) lat = d["latency_seconds"] or {} rows = d["rows"] bad = [] for kind, rs in rows.items(): for r in rs: if r.get("correct") is False: bad.append(f"{r['id']}") print(f"{d['model']:12s} " f"noul {d['accuracy']['noul']:.2f} " f"choice {d['accuracy']['choice']:.2f} " f"scoreMAE {d['score_mae']} " f"ECE {d['ece_10bin']:.3f} " f"flip {d['flip_rate']} " f"p50 {(lat.get('p50') or 0)*1000:.1f}ms " f"p95 {(lat.get('p95') or 0)*1000:.1f}ms " f"misses: {','.join(bad) if bad else '-'}") .
